import{_ as t,o as a,c as h,a3 as o}from"./chunks/framework.DX_KL3e0.js";const u=JSON.parse('{"title":"Chấm công vào / ra","description":"","frontmatter":{},"headers":[],"relativePath":"huong-dan/cham-cong.md","filePath":"huong-dan/cham-cong.md","lastUpdated":1782145991000}'),c={name:"huong-dan/cham-cong.md"};function i(r,n,g,s,l,e){return a(),h("div",null,[...n[0]||(n[0]=[o('<h1 id="cham-cong-vao-ra" tabindex="-1">Chấm công vào / ra <a class="header-anchor" href="#cham-cong-vao-ra" aria-label="Permalink to &quot;Chấm công vào / ra&quot;">​</a></h1><blockquote><p><strong>🎯 Mục tiêu:</strong> Điểm danh đầu ca và cuối ca. <strong>👤 Ai làm được:</strong> Mọi nhân sự.</p></blockquote><div class="info custom-block"><p class="custom-block-title">Đa số chấm bằng máy vân tay</p><p><strong>Phần lớn nhân viên chấm công bằng máy vân tay</strong> đặt tại văn phòng — đặt ngón tay khi vào ca và khi tan ca, dữ liệu tự đẩy về hệ thống. Chỉ <strong>một số bộ phận đặc thù</strong> chấm công bằng <strong>điện thoại</strong> (ảnh selfie + GPS).</p></div><h2 id="cach-1-—-may-van-tay-đa-so-nhan-vien" tabindex="-1">Cách 1 — Máy vân tay (đa số nhân viên) <a class="header-anchor" href="#cach-1-—-may-van-tay-đa-so-nhan-vien" aria-label="Permalink to &quot;Cách 1 — Máy vân tay (đa số nhân viên)&quot;">​</a></h2><ol><li>Đặt ngón tay lên <strong>máy vân tay</strong> ở văn phòng khi <strong>vào ca</strong> và khi <strong>tan ca</strong>.</li><li>Dữ liệu tự đẩy về hệ thống (cập nhật realtime). Xem lại tại <strong>Dữ Liệu Chấm Công → Tra Cứu Dữ Liệu Công</strong> (tab <strong>Vân Tay</strong>).</li></ol><p>→ Quên hoặc lỗi chấm? Khai <a href="/help/huong-dan/bu-cong-tang-ca.html">Bù công</a> để quản lý duyệt bổ sung.</p><h2 id="cach-2-—-đien-thoai-chi-bo-phan-đac-thu" tabindex="-1">Cách 2 — Điện thoại (chỉ bộ phận đặc thù) <a class="header-anchor" href="#cach-2-—-đien-thoai-chi-bo-phan-đac-thu" aria-label="Permalink to &quot;Cách 2 — Điện thoại (chỉ bộ phận đặc thù)&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Bắt buộc ảnh + GPS</p><p>Phải có <strong>ảnh selfie</strong> và <strong>vị trí GPS</strong> mới chấm được. GPS chỉ chạy trên HTTPS; trên Safari iPhone/iPad vào <em>Cài đặt → Safari → Vị trí</em> chọn &quot;Hỏi&quot; hoặc &quot;Cho phép&quot;.</p></div><ol><li>Vào <strong>Dữ Liệu Chấm Công</strong> → <strong>Chấm Công</strong>.</li><li>Bật định vị — ô <strong>Vị Trí (GPS)</strong> chuyển xanh khi lấy được tọa độ (chưa có thì bấm biểu tượng làm mới).</li><li>Bấm <strong>Chụp ảnh xác nhận</strong> → chụp selfie (ảnh tự đóng dấu giờ + toạ độ GPS).</li><li>Bấm <strong>Điểm Danh VÀO</strong> (đầu ca) hoặc <strong>Điểm Danh RA</strong> (cuối ca) — hệ thống tự gợi ý nút đúng.</li></ol><h2 id="✅-ket-qua" tabindex="-1">✅ Kết quả <a class="header-anchor" href="#✅-ket-qua" aria-label="Permalink to &quot;✅ Kết quả&quot;">​</a></h2><p>Lần chấm hiện ở <strong>Lịch sử hôm nay</strong> và trong bảng công tháng, kèm nhãn nguồn <strong>Máy</strong> (vân tay) hoặc <strong>App</strong> (điện thoại). Chấm bằng điện thoại còn nhận <strong>thông báo Telegram</strong> xác nhận.</p><h2 id="💡-meo-luu-y" tabindex="-1">💡 Mẹo &amp; lưu ý <a class="header-anchor" href="#💡-meo-luu-y" aria-label="Permalink to &quot;💡 Mẹo &amp; lưu ý&quot;">​</a></h2><ul><li>Đã bấm vân tay nhưng app chưa thấy giờ? Dữ liệu máy đẩy về định kỳ — trang <strong>Tra Cứu</strong> cập nhật realtime; chờ chốc lát hoặc bấm <strong>Làm mới</strong>.</li><li>Mới vào làm, chấm vân tay mà không lên dữ liệu → có thể <strong>chưa được gán mã máy</strong>; báo HCNS gán mã chấm công cho bạn.</li><li>Quên chấm Ra → báo quản lý, dùng <a href="/help/huong-dan/bu-cong-tang-ca.html">Bù công</a>.</li></ul><p><em>Chi tiết: <a href="/help/chuc-nang/cham-cong.html#_1-cham-cong-vao-ra">Dữ liệu Chấm công</a></em></p>',14)])])}const p=t(c,[["render",i]]);export{u as __pageData,p as default};
